/*
 * catalog/pricing.json -> catalog/credit-packs.json
 *
 * pricing.json carries our engine costs and margins and is blocked from the
 * public site in _redirects. The pack chooser on the account page needs the
 * marketing half of the same rows, so this writes a file containing only what a
 * customer may see: id, credits, price, bonus.
 *
 * The generated file is display only. create-checkout looks the pack up in
 * pricing.json server-side and charges from THAT, so a stale or edited public
 * file can show a wrong number but can never buy credits at the wrong price.
 *
 *   node tools/build-credit-packs.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';

const src = JSON.parse(readFileSync('catalog/pricing.json', 'utf8'));
const packs = (src.credit_packs || []).map((p) => ({
  id: p.id, credits: p.credits, usd: p.usd, bonus_pct: p.bonus_pct,
}));
if (!packs.length) { console.error('no credit_packs in pricing.json'); process.exit(1); }

/*
 * The post-render action prices, for the same reason the packs are here.
 *
 * account.js used to carry these as string literals under a comment saying
 * they mirrored pricing.json. They did not: measured 2026-08-15 the chips
 * advertised $4/$9/$4 while the server charged $3/$7/$3, so every buyer was
 * quoted more than they were billed. Publishing them from the one file that
 * decides the charge is what stops that happening a second time.
 */
const ACTION_KEYS = ['revoice', 'translate', 'upscale'];
const actions = {};
for (const k of ACTION_KEYS) {
  const item = (src.items || {})[k];
  if (!item || typeof item.retail_usd !== 'number') {
    console.error(`no retail_usd for item "${k}" in pricing.json`); process.exit(1);
  }
  actions[k] = item.retail_usd;
}

writeFileSync('catalog/credit-packs.json', JSON.stringify({
  _readme: 'Generated by tools/build-credit-packs.mjs from catalog/pricing.json. Display only; create-checkout prices from pricing.json.',
  credit_packs: packs,
  action_usd: actions,
}, null, 2) + '\n');

console.log('wrote catalog/credit-packs.json:', packs.map((p) => `${p.id} ${p.credits}cr $${p.usd}`).join(', '));
console.log('  action prices:', ACTION_KEYS.map((k) => `${k} $${actions[k]}`).join(', '));
